static void em_modify_pdv_length(
    const rule_info_t *rule, int verdict, uint64_t timestamp,
    uint64_t counter, const mmt_array_t * const trace) {
    uint32_t new_length;

    new_length = 50;
    log_info("Negative PDV Length: Setting to 0xFFFFFFFF");

    // Replace with new PDV length
    replace_dicom_attribute(701, 10, &new_length, 0);

    forward_packet();
}
